<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api} from './session'
import SupplierInput from './SupplierInput.vue'
const props=defineProps<{context:any}>(),emit=defineEmits<{completed:[mode:string],close:[]}>()
const rows=ref<any[]>([]),loading=ref(false),busy=ref(false),error=ref(''),lockInventory=ref(false),request=ref(''),finished=ref(false)
const purchase=computed(()=>props.context.mode==='purchase')
const routes=[['UK_air','英国空派'],['UK_truck','英国卡航'],['UK_sea','英国海运'],['DE_air','德国空派'],['DE_truck','德国卡航'],['DE_sea','德国海运']]
const bulkDate=ref(''),bulkSupplier=ref(''),supplierDates=ref<Record<string,string>>({})
const money=(n:any)=>Number(n||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:4})
const id=()=>{const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]!&15)|64;b[8]=(b[8]!&63)|128;const s=Array.from(b,v=>v.toString(16).padStart(2,'0')).join('');return `${s.slice(0,8)}-${s.slice(8,12)}-${s.slice(12,16)}-${s.slice(16,20)}-${s.slice(20)}`}
const total=(r:any):number=>purchase.value?Number(r.quantity||0):Object.values(r.quantities||{}).reduce<number>((s,v)=>s+Number(v||0),0)
const totalQuantity=computed(()=>rows.value.reduce((s,r)=>s+total(r),0))
const price=computed(()=>rows.value.reduce((s,r)=>s+Math.round((Number(r.quantity||0)*Number(r.unit_cost||0)+Number(r.extra_cost||0))*10000),0)/10000)
function stores(r:any){if(r.added)return r.store;return [...new Set((r.allocations||[]).map((a:any)=>a.store))].join(' / ')}
function refs(r:any,key:string){return [...new Set((r.listings||[]).filter((l:any)=>l[key]).map((l:any)=>`${l.store}: ${l[key]}`))].join('\n')||'—'}
async function load(){loading.value=true;error.value='';try{const d=await api(purchase.value?'/procurement/preview':'/procurement/flow/dispatch-preview',purchase.value?{plans:props.context.items}:{kind:props.context.kind,items:props.context.items});supplierDates.value=d.supplier_dates||{};rows.value=(purchase.value?d.groups:d.rows).map((r:any)=>({...r,unit_cost:r.unit_cost==null?null:Number(r.unit_cost),extra_cost:0,expected_date:r.expected_date||'',quantities:{...Object.fromEntries(routes.map(([k])=>[k,0])),...r.quantities}}));request.value=id()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function applyBulk(){for(const r of rows.value){if(bulkSupplier.value.trim())r.supplier=bulkSupplier.value.trim();if(bulkDate.value)r.expected_date=bulkDate.value}}
function supplierChanged(row:any){const other=rows.value.find(r=>r!==row&&r.supplier.trim()===row.supplier.trim());row.expected_date=other?.expected_date||supplierDates.value[row.supplier.trim()]||row.expected_date}
function dateChanged(row:any){for(const r of rows.value)if(r.supplier.trim()===row.supplier.trim())r.expected_date=row.expected_date}
const productDialog=ref(false),products=ref<any[]>([]),productLoading=ref(false),productId=ref<number|null>(null),productStore=ref(''),warehouseId=ref<number|null>(null),warehouses=ref<any[]>([])
let productSearch=0
async function findProducts(q:string){const n=++productSearch;productLoading.value=true;try{const d=await api('/products?'+new URLSearchParams({q,page_size:'50'}));if(n===productSearch)products.value=d.rows}catch(e){ElMessage.error((e as Error).message)}finally{if(n===productSearch)productLoading.value=false}}
async function openProduct(){productId.value=null;productStore.value=rows.value[0]?.allocations?.[0]?.store||props.context.stores?.[0]||'';warehouseId.value=rows.value[0]?.warehouse_id||null;try{const d=await api('/procurement/options');warehouses.value=d.warehouses;productDialog.value=true;void findProducts('')}catch(e){ElMessage.error((e as Error).message)}}
async function addProduct(){const p=products.value.find(p=>p.id===productId.value);if(!p||!warehouseId.value||!productStore.value){ElMessage.warning('请选择产品、店铺和仓库');return}if(rows.value.some(r=>r.product_id===p.id&&r.warehouse_id===warehouseId.value)){ElMessage.warning('该产品和仓库已在列表中，请直接修改采购量');return}
 try{const d=await api('/procurement/product-references',{product_id:p.id,store:productStore.value});rows.value.push({key:'new-'+id(),added:true,product_id:p.id,warehouse_id:warehouseId.value,warehouse_name:warehouses.value.find(w=>w.id===warehouseId.value)?.name,store:productStore.value,code:p.code,name:p.name,image_url:p.image_url,quantity:1,unit_cost:p.cost_cny==null?null:Number(p.cost_cny),extra_cost:0,supplier:bulkSupplier.value.trim()||p.primary_supplier||'',expected_date:bulkDate.value||supplierDates.value[p.primary_supplier]||'',allocations:[],listings:d.rows});supplierChanged(rows.value[rows.value.length-1]);productDialog.value=false}catch(e){ElMessage.error((e as Error).message)}}
let fingerprint=''
async function save(){
 if(busy.value||!rows.value.length)return
 error.value=''
 if(purchase.value&&rows.value.some(r=>!Number.isInteger(r.quantity)||r.quantity<1||r.unit_cost==null||!(r.supplier||'').trim()||!r.expected_date)){error.value='请填写每行的正整数采购量、供应商、预计到货日期和单价';return}
 if(!purchase.value&&rows.value.some(r=>!r.store||total(r)<=0||total(r)>r.quantity)){error.value='请选择店铺，并填写不超过可安排量的发货数量';return}
 const spec=(r:any)=>({product_id:r.product_id,warehouse_id:r.warehouse_id,quantity:r.quantity,unit_cost:r.unit_cost,extra_cost:r.extra_cost,supplier:r.supplier,expected_date:r.expected_date});
 const body=purchase.value?{plans:props.context.items,groups:rows.value.filter(r=>!r.added).map(spec),additions:rows.value.filter(r=>r.added).map(r=>({...spec(r),store:r.store}))}:{kind:props.context.kind,items:props.context.items,lock_inventory:lockInventory.value,rows:rows.value.map(r=>({key:r.key,store:r.store,quantities:Object.fromEntries(routes.map(([k])=>[k,r.quantities[k!]||0]))}))}
 const next=JSON.stringify(body);if(fingerprint&&fingerprint!==next)request.value=id();fingerprint=next;busy.value=true
 try{const d=await api(purchase.value?'/procurement/generate':'/procurement/flow/dispatch',{...body,request_id:request.value});finished.value=true;ElMessage.success(purchase.value?`已生成 ${new Set(d.orders.map((o:any)=>o.number)).size} 张采购单`:`已生成 ${d.created_ids.length} 个发货计划`);emit('completed',props.context.mode)}catch(e){error.value=(e as Error).message}finally{busy.value=false}
}
async function canLeave(){if(busy.value)return false;if(finished.value||!rows.value.length)return true;try{await ElMessageBox.confirm('关闭后将放弃本页未提交的内容。','关闭生成页面',{confirmButtonText:'关闭',cancelButtonText:'继续编辑'});return true}catch{return false}}
defineExpose({canLeave})
onMounted(load)
</script>
<template><section class="procurement-generate" v-loading="loading"><header><h2>{{purchase?'生成采购单':'生成发货计划'}}</h2><div><el-button v-if="purchase" type="primary" :disabled="busy||loading" @click="openProduct">新增产品</el-button><el-button :disabled="busy" @click="emit('close')">返回采购管理</el-button></div></header><el-alert v-if="error" type="error" :title="error" :closable="false"/><div v-if="!loading&&!rows.length"><el-button @click="load">重新加载</el-button></div><el-form :disabled="busy"><div v-if="purchase" class="generate-settings"><el-form-item label="批量供应商"><SupplierInput v-model="bulkSupplier" placeholder="保留各行供应商"/></el-form-item><el-form-item label="批量预计到货日期"><el-date-picker v-model="bulkDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-button @click="applyBulk">应用到全部</el-button></div><div v-else class="generate-settings"><b>库存处理</b><el-radio-group v-model="lockInventory"><el-radio :value="false">不锁定库存</el-radio><el-radio :value="true">校验并锁定库存</el-radio></el-radio-group></div>
<el-table :data="rows" border row-key="key" class="generation-table"><el-table-column label="图片" width="85" fixed="left"><template #default="{row}"><el-image :src="row.image_url||''" fit="contain" class="image"><template #error>无图</template></el-image></template></el-table-column><el-table-column label="品名 / 标品编码" min-width="240" fixed="left"><template #default="{row}"><strong>{{row.name}}</strong><div>{{row.code}}</div><small>{{purchase?(row.added?'新增采购':[...new Set(row.allocations.map((a:any)=>a.batch_code))].join(' / ')):row.numbers.join(' / ')}}</small></template></el-table-column><el-table-column label="店铺" width="150"><template #default="{row}"><span v-if="purchase">{{stores(row)}}</span><el-select v-else v-model="row.store" :disabled="row.fixed_store" placeholder="请选择"><el-option v-for="s in context.stores" :key="s" :value="s" :label="s"/></el-select></template></el-table-column><el-table-column label="SKU" width="230"><template #default="{row}"><div class="references">{{refs(row,'sku')}}</div></template></el-table-column><el-table-column label="FNSKU" width="200"><template #default="{row}"><div class="references">{{refs(row,'fnsku')}}</div></template></el-table-column><el-table-column label="仓库" prop="warehouse_name" width="130"/><el-table-column :label="purchase?'采购量':'可安排量'" width="150" align="center"><template #default="{row}"><el-input-number v-if="purchase" v-model="row.quantity" :min="1" :max="100000000" :precision="0" :controls="false" style="width:100%" :aria-label="'采购量 '+row.code"/><span v-else>{{row.quantity}}</span></template></el-table-column>
<template v-if="purchase"><el-table-column label="供应商" width="220"><template #default="{row}"><SupplierInput v-model="row.supplier" @change="supplierChanged(row)"/></template></el-table-column><el-table-column label="预计到货日期" width="170"><template #default="{row}"><el-date-picker v-model="row.expected_date" style="width:100%" type="date" value-format="YYYY-MM-DD" @change="dateChanged(row)"/></template></el-table-column><el-table-column label="单价(¥)" width="150"><template #default="{row}"><el-input-number v-model="row.unit_cost" :min="0" :max="100000000" :precision="4" :controls="false" style="width:100%"/></template></el-table-column><el-table-column label="其他费用(¥)" width="150"><template #default="{row}"><el-input-number v-model="row.extra_cost" :min="0" :max="100000000" :precision="4" :controls="false" style="width:100%"/></template></el-table-column><el-table-column label="价格(¥)" width="125" align="right"><template #default="{row}">{{money(row.quantity*row.unit_cost)}}</template></el-table-column></template>
<template v-else><el-table-column v-for="[key,label] in routes" :key="key" :label="label" width="120"><template #default="{row}"><el-input-number v-model="row.quantities[key!]" :min="0" :max="row.quantity" :precision="0" :controls="false" style="width:100%" :aria-label="label+' '+row.code"/></template></el-table-column><el-table-column label="本次合计" width="100"><template #default="{row}">{{total(row)}}</template></el-table-column></template><el-table-column v-if="purchase" label="操作" width="80" fixed="right"><template #default="{row}"><el-button v-if="row.added" link type="danger" @click="rows=rows.filter(r=>r!==row)">移除</el-button></template></el-table-column></el-table></el-form>
<p class="generation-note">{{purchase?'相同供应商的商品合并为一张采购单，预计到货日期同步；提交前请核对单价和供应商。':'每行按国家和渠道填写发货数量，合计不能超过可安排量；同店铺、同仓库一起生成。'}}</p><footer><span>共 {{rows.length}} 条商品 · {{totalQuantity}} 件 <b v-if="purchase">　总价 ¥{{money(price)}}</b></span><div><el-button :disabled="busy" @click="emit('close')">取消</el-button><el-button type="primary" :loading="busy" :disabled="loading||!rows.length||finished" @click="save">{{purchase?'确认生成采购单':'确认生成发货计划'}}</el-button></div></footer><el-dialog v-model="productDialog" title="新增采购产品" width="620px" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="产品"><el-select v-model="productId" filterable remote :remote-method="findProducts" :loading="productLoading" placeholder="搜索标品编码或品名" style="width:100%"><el-option v-for="p in products" :key="p.id" :value="p.id" :label="p.code+' · '+p.name"/></el-select></el-form-item><el-form-item label="店铺"><el-select v-model="productStore"><el-option v-for="s in context.stores" :key="s" :value="s" :label="s"/></el-select></el-form-item><el-form-item label="收货仓库"><el-select v-model="warehouseId"><el-option v-for="w in warehouses" :key="w.id" :value="w.id" :label="w.name"/></el-select></el-form-item></el-form><template #footer><el-button @click="productDialog=false">取消</el-button><el-button type="primary" @click="addProduct">添加</el-button></template></el-dialog></section></template>
<style scoped>.procurement-generate{padding:24px;background:white;min-height:75vh}.procurement-generate header{display:flex;align-items:center;justify-content:space-between;margin-bottom:22px}.procurement-generate h2{margin:0;font-size:22px}.generate-settings{display:flex;align-items:center;flex-wrap:wrap;gap:20px;padding:20px;background:#f2f7f4;margin:16px 0}.generate-settings .el-form-item{margin:0}.image{width:52px;height:52px;border-radius:6px}.references{white-space:pre-line;font-size:12px;overflow-wrap:anywhere}small,.generation-note{color:#809589}.generation-note{font-size:13px;margin:18px 0}footer{position:sticky;bottom:0;background:white;display:flex;justify-content:space-between;align-items:center;padding:20px 0;border-top:1px solid #e4ece7;z-index:5}.procurement-generate :deep(.el-table .cell){line-height:1.8}</style>
